import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CZqXuAiL.js";const p=JSON.parse('{"title":"Everything OpenShield-XDP Does","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/features/index.md","filePath":"openshield-xdp/features/index.md","lastUpdated":1785959583000}'),s={name:"openshield-xdp/features/index.md"};function n(i,e,l,d,c,g){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="everything-openshield-xdp-does" tabindex="-1">Everything OpenShield-XDP Does <a class="header-anchor" href="#everything-openshield-xdp-does" aria-label="Permalink to &quot;Everything OpenShield-XDP Does&quot;">​</a></h1><p>This is the complete map of the product — every attack class it stops, every mitigation mechanism, every operator tool, and every silent guardian that protects you without ever asking for attention. Nothing is held back; if a feature exists in the binary, it&#39;s on this page.</p><p>OpenShield-XDP inspects and drops attack traffic <strong>inside the NIC driver</strong> — before the kernel allocates an skb, before iptables, before your application sees anything. One attached core handles <strong>10M+ packets/sec</strong> at ~300–500ns per packet on the normal path.</p><hr><h2 id="attack-coverage-—-what-it-stops" tabindex="-1">Attack coverage — what it stops <a class="header-anchor" href="#attack-coverage-—-what-it-stops" aria-label="Permalink to &quot;Attack coverage — what it stops&quot;">​</a></h2><p>Every attack class below is detected and countered at XDP line rate. Details per class: <a href="/pingless-studios-docs/openshield-xdp/features/attack-coverage">Attack Coverage</a>.</p><table tabindex="0"><thead><tr><th>Attack class</th><th>How it&#39;s countered</th></tr></thead><tbody><tr><td><strong>SYN flood</strong></td><td>Per-IP SYN-PPS scoring (magnitude-scaled up to 8×), SYN/FIN ratio check, rate-based SYNPROXY, connection-rate limiter</td></tr><tr><td><strong>UDP flood</strong></td><td>Per-IP UDP-PPS scoring, per-port attack cap, L7 signatures, behavior engine</td></tr><tr><td><strong>TCP flood (non-SYN)</strong></td><td>TCP-PPS scoring, blind-packet enforcement, attack-mode per-IP hard cap</td></tr><tr><td><strong>ICMP / ping flood</strong></td><td>ICMP-PPS scoring (highest default score weight — ICMP has no legit high-rate use)</td></tr><tr><td><strong>UDP amplification / reflection</strong></td><td>8 configurable reflection ports (DNS, NTP, SSDP, Memcached, QOTD, CHARGEN, RIP, TFTP) with payload minimums + DNS QR-bit verification, plus curated L7 signatures (CLDAP, SNMP, WS-Discovery…)</td></tr><tr><td><strong>SYN-ACK reflection</strong></td><td>Connection tracking drops SYN-ACKs with no prior SYN</td></tr><tr><td><strong>Blind ACK / RST floods</strong></td><td>Conn-track enforcement: RST or expired-SYN packets to server ports are dropped</td></tr><tr><td><strong>Spoofed / rotating-source floods</strong></td><td>16-bucket source-IP entropy sketch, new-source flood temp-bans, rotation-proof per-destination-port aggregate cap</td></tr><tr><td><strong>Carpet bombing / subnet attacks</strong></td><td>Automatic /24 (IPv4) and /64 (IPv6) subnet escalation into the LPM trie at 2× ban duration</td></tr><tr><td><strong>Fragmentation attacks</strong></td><td>Optional drop of all fragmented packets (v4 MF/offset + v6 fragment headers)</td></tr><tr><td><strong>TCP flag abuse / scans</strong></td><td>Bogus-flag validation (SYN+FIN, SYN+RST, FIN+RST, all-flags, NULL, bad data offset)</td></tr><tr><td><strong>Malformed / truncated packets</strong></td><td>L3 checks (version, IHL, length, extension-header overflow) + L4 bounds</td></tr><tr><td><strong>Bogon / spoofed ranges</strong></td><td>11 IPv4 + 6 IPv6 reserved-range source filters</td></tr><tr><td><strong>L7 pattern attacks</strong></td><td>16-slot mask-and-compare signature engine (1–8 byte patterns, offset 0–255, payload-size guards)</td></tr><tr><td><strong>Port scans</strong></td><td>New-source limits, connection-rate limit, per-IP scoring, TTL/size anomaly suspicion</td></tr><tr><td><strong>Low-and-slow / slow climbs</strong></td><td>Baseline-anchored partial scoring during attacks + a baseline-learning ceiling that refuses to learn attack traffic (kills the &quot;slow climb&quot; bypass)</td></tr><tr><td><strong>Bot-like behavioral floods</strong></td><td>Behavior engine: per-port baselines, source clustering by packet size/TTL/timing similarity, confidence-scored auto-blocking</td></tr><tr><td><strong>CPU-exhaustion mega-floods</strong></td><td>Per-CPU panic circuit breaker with userspace cross-CPU coordination</td></tr></tbody></table><p>Attacks are classified live as <strong>SYN_FLOOD, UDP_FLOOD, UDP_AMPLIFICATION, ICMP_FLOOD, TCP_FLOOD, AMPLIFICATION, or MIXED</strong> — with automatic re-classification if the attack morphs mid-flight.</p><hr><h2 id="mitigation-engine" tabindex="-1">Mitigation engine <a class="header-anchor" href="#mitigation-engine" aria-label="Permalink to &quot;Mitigation engine&quot;">​</a></h2><ul><li><strong>Suspicion scoring</strong> — six per-IP metrics (PPS, BPS, TCP, UDP, ICMP, SYN) add to a decaying score; the higher above threshold a source is, the faster it scores (up to 8×). Score crosses the limit → banned.</li><li><strong>Ban system</strong> — 2M-entry IPv4 + 200K IPv6 ban maps. Repeat offenders get lower effective thresholds and 7-level star durations (×1 → ×32). Userspace decays stars after a clean period.</li><li><strong>Subnet escalation</strong> — too many bans from one prefix → the whole /24 (or /64) is banned in the LPM trie, automatically.</li><li><strong>Rate limiting, two modes</strong> — threshold scoring (burst-shaped) or token bucket (smooth, burst-tolerant).</li><li><strong>Attack mode</strong> — on a declared attack: all thresholds tighten (configurable multiplier), a hard per-IP PPS cap engages, and a <strong>per-destination-port aggregate cap</strong> stops rotating floods that keep every per-IP counter cold — with player protection so legitimate clients stay connected.</li><li><strong>Panic circuit breaker</strong> — per-CPU probabilistic bulk drop when a core exceeds its PPS rate, coordinated globally for extreme floods.</li><li><strong>SYNPROXY</strong> — rate-based SYN flood gate, portable to every supported kernel.</li><li><strong>Connection tracking</strong> — handshake observation with blind-packet enforcement; long-lived connections are kept alive by sliding liveness.</li><li><strong>Connection-state tracking (v2.12)</strong> — every connection is followed individually: replies to your own outbound connections are recognized precisely, blind ACK/RST floods are judged per connection, and million-source rotating floods are counted lock-free with no core slowdown.</li><li><strong>L7 signatures</strong> — 16 slots; new signatures can be promoted from real attack fingerprints with one keypress in the TUI.</li><li><strong>Geo blocking</strong> — block or allow-list entire countries; ranges resolve from MaxMind GeoLite2 and enforce as subnet bans. <a href="/pingless-studios-docs/openshield-xdp/user-guide/geo-blocking">Guide</a></li><li><strong>Blocklists</strong> — manual bans (with optional notes), file imports, and <strong>auto-fetch feeds</strong> (11 curated categories + your own URLs) with <code>vps</code>/<code>dedicated</code> modes — dedicated mode skips cloud-provider ranges so your customers&#39; legit nodes are never feed-banned. <a href="/pingless-studios-docs/openshield-xdp/user-guide/auto-fetch">Guide</a></li><li><strong>Validation filters</strong> — bogon/private ranges, bogus TCP flags, malformed packets, fragments, MAC filter (blacklist/whitelist mode, ARP always exempt).</li><li><strong>Statistical anomaly detection</strong> — TTL anomalies, packet-size anomalies, connection-rate spikes, SYN/FIN ratio, entropy spoofing.</li><li><strong>Whitelist</strong> — per-IP flags (full bypass, skip-ban, skip-rate, skip-validation) with Bloom-filter acceleration.</li></ul><hr><h2 id="silent-guardians" tabindex="-1">Silent guardians <a class="header-anchor" href="#silent-guardians" aria-label="Permalink to &quot;Silent guardians&quot;">​</a></h2><p>The protections you never configured and never notice — until you learn they&#39;re there. Full stories: <a href="/pingless-studios-docs/openshield-xdp/features/silent-guardians">Silent Guardians</a>.</p><ul><li><strong>Your SFTP uploads never get you banned</strong> — proven TCP connections (real handshake + real data) are exempt from rate scoring. Bulk transfers are indistinguishable from floods by rate alone; OpenShield proves the connection instead.</li><li><strong>Your own downloads never fake an attack</strong> — replies to the server&#39;s own outbound connections (apt, GeoIP updates, blocklist fetches, backups) skip rate limiting <em>and</em> attack detection.</li><li><strong>Your admin IP whitelists itself</strong> — the IP you SSH in from is auto-whitelisted on every load and persisted across reboots.</li><li><strong>Players never disconnect mid-attack</strong> — established and pre-attack sources are exempt from the per-port attack cap.</li><li><strong>The baseline can&#39;t be poisoned</strong> — learning freezes during attacks and refuses above-trigger traffic even when no attack is declared. Since v2.12 the 30-day history is merged with robust statistics, so a slow multi-day ramp can&#39;t train the baseline upward either.</li><li><strong>Season-aware thresholds (v2.12)</strong> — hour-of-day patterns are learned and the trigger band relaxes automatically during predictably busy hours; it only ever relaxes, never tightens.</li><li><strong>Ban storage protects itself (v2.12)</strong> — approaching-full storage warns you, reaps expired entries, and only ever reclaims auto-fetched blocklist entries (which re-fetch themselves); attack-driven bans are never pressure-deleted.</li><li><strong>No false attack storms</strong> — declaration hysteresis, recovery bands, re-trigger cooldowns, anti-flap re-classification, and a startup warmup window.</li><li><strong>The firewall protects itself</strong> — log flood pauses, BPF event rate limits, alert queues that drop rather than block the datapath.</li><li><strong>Crash-proof state</strong> — bans, baseline, geo blocks, ban notes and schedules survive restarts; the TUI never takes the firewall down when you close it.</li><li><strong>Fail-open where it matters</strong> — no config loaded = pass all; empty MAC whitelist = pass; broken feeds never perma-block.</li></ul><hr><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h2><ul><li><strong>TUI dashboard</strong> (<code>openshield stats</code>) — 10 screens: live graphs, traffic analysis, bans, logs, system status, a <strong>live config editor</strong>, attack history with one-key bulk-blacklist and fingerprints, access management, and geo blocking. Closing it never stops protection.</li><li><strong>CLI</strong> — every operation scriptable: <code>load</code>, <code>unload</code>, <code>status</code>, <code>stats</code>, <code>reload</code>, <code>whitelist</code>, <code>blacklist</code>, <code>license</code>, <code>key</code>, <code>report</code>, <code>behavior</code>, <code>schedule</code>, <code>fix</code>, <code>doctor</code>, <code>upgrade</code>, <code>reconfigure</code>… with per-command help (<code>openshield help &lt;command&gt;</code>). <a href="/pingless-studios-docs/openshield-xdp/user-guide/cli">CLI reference</a></li><li><strong>Metrics HTTP API</strong> — optional, off by default; everything the TUI shows as JSON, API-key guarded, rate-limited, allowlist-able. <a href="/pingless-studios-docs/openshield-xdp/user-guide/metrics-api">Metrics API</a></li><li><strong>Per-tenant visibility (v2.12)</strong> — on multi-IP dedicated hosts every hosted IP gets a <code>normal</code> / <code>elevated</code> / <code>under_attack</code> state in the TUI targets panel, attack reports, and <code>GET /metrics/targets</code> (auto-detected; single-IP VPS installs are unaffected).</li><li><strong>Discord/Slack webhooks</strong> — attack start, growing-cadence progress updates, and a full end report: peak/avg/P95 PPS &amp; Gbps, IPs involved, mitigation time, <strong>per-country breakdown with flags</strong>, graph banner, and the forensics bundle attached. A generic JSON webhook (v2.12) mirrors every event to your own endpoint for custom integrations.</li><li><strong><code>openshield doctor</code> (v2.12)</strong> — one-command environment health check (kernel, BTF, XDP attach, NIC driver, config, forensics disk, license) with <code>--json</code> output for support.</li><li><strong>Forensics</strong> — every attack gets a directory: report, involved IPs, traffic fingerprint (with a suggested L7 rule), config snapshot, and PCAP (attack-triggered or a rolling ~3-minute ring).</li><li><strong>Reports</strong> — daily/weekly/monthly aggregates with capacity prediction and geo breakdowns, optionally dispatched to your webhook.</li></ul><hr><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><ul><li><strong>Fully annotated YAML</strong> — every setting documented inline with safe ranges and trade-offs.</li><li><strong>Live editing</strong> — <code>openshield reload</code> and the TUI editor apply runtime-safe fields instantly and persist them; read-only fields explain why.</li><li><strong>70 presets × 25 workload types</strong> — from Minecraft to CDN edge to database; the installer recommends one from your workload mix. <a href="/pingless-studios-docs/openshield-xdp/configuration/profiles">Profiles</a></li><li><strong>Per-port threshold overrides</strong> — custom PPS/BPS limits for specific ports or ranges (e.g. relaxed SFTP, strict game port).</li><li><strong>Boot autostart</strong> — <code>openshield load -always</code> enables the hardened systemd unit (network-online ordering, infinite restart) so protection comes back after every reboot.</li></ul><hr><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>HWID-bound license keys validated against the Altis license server, with offline grace and cached-HWID tolerance.</li><li><code>enforce</code> + <code>hard_fail</code> — unlicensed installs refuse to load; a failed refresh unloads.</li><li>Feature gating happens in the BPF config map — re-licensing restores exactly the features that were gated, automatically.</li></ul><hr><h2 id="platform" tabindex="-1">Platform <a class="header-anchor" href="#platform" aria-label="Permalink to &quot;Platform&quot;">​</a></h2><ul><li><strong>Dual-stack</strong> IPv4/IPv6 with separate maps, extension-header walking, and v6 /64 escalation.</li><li><strong>XDP native / generic / skb</strong> modes — runs on virtio, Xen, Realtek and everything else.</li><li><strong>Kernel 5.15 → latest</strong> with zero user fixes — the core promise; compile-time feature gates, freplace hot-patching as an opt-in on 6.10+.</li><li><strong>Map sizing</strong> for your RAM: ban maps already scale to 2M sources on ~1GB.</li><li><strong>Obfuscated prebuilt releases</strong> (garble) — zero source in the production zip; source zip available separately.</li></ul><hr><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Latency</th></tr></thead><tbody><tr><td>Normal path (all checks pass)</td><td>~300–500 ns</td></tr><tr><td>Attack path (all modules active)</td><td>~1–2 µs</td></tr><tr><td>At 10M PPS</td><td>~50–70% single-core utilization</td></tr></tbody></table><p>Deep dive: <a href="/pingless-studios-docs/openshield-xdp/architecture/overview">Architecture</a> · <a href="/pingless-studios-docs/openshield-xdp/performance/overview">Performance</a></p>',31)])])}const u=t(s,[["render",n]]);export{p as __pageData,u as default};
